var t=[{day:"2026-08-20",n:53,label:"Day 1"},{day:"2026-08-21",n:12,label:"Day 2"},{day:"2026-08-22",n:1,label:"Day 3",thin:!0},{day:"2026-08-23",n:6,label:"Day 4"},{day:"2026-08-24",n:0,label:"Day 5",thin:!0},{day:"2026-08-25",n:43,label:"Day 6"},{day:"2026-08-26",n:18,label:"Day 7"},{day:"2026-08-27",n:17,label:"Day 8"}],a=[{day:"2026-08-20",title:"Measured, not eyeballed"},{day:"2026-08-21",title:"The in-call screen"},{day:"2026-08-23",title:"The shared screen becomes a desktop"},{day:"2026-08-25",title:"Pinned and presenting layouts"},{day:"2026-08-26",title:"Read as a stranger would read it"},{day:"2026-08-27",title:"The call gives its own demo"}],n=[{n:1,name:"Analysis and planning",body:"Drive the real product and read it, rather than guessing from memory. Geometry, colours and timings come off the live DOM. Anything that cannot be measured is written down as unmeasured before a line of code is committed to it.",outputs:["A measured baseline","A written plan, reviewed twice","A list of what could not be read"]},{n:2,name:"Execution",body:"Build to the plan, in small commits, with the reasoning left in the comments. Where a number came from a measurement the comment says so; where it came from judgement, it says that instead.",outputs:["Working code","Comments that explain why, not what"]},{n:3,name:"QA and bug fixes",body:"Drive the built thing the way a person would, in a real browser, with real clicks. This phase has caught more than review did, including a bug where every click inside a window was silently discarded, which three rounds of synthetic tests had passed.",outputs:["Findings, verified before they are called fixed","Retractions when a diagnosis was wrong"]},{n:4,name:"Big-picture review",body:"At the end of a batch rather than per task: step out of the code and read the artefact as its audiences will. This is where the framing problems surface, and they have consistently been more expensive than the code problems.",outputs:["A perception pass","A ranked list of what to fix next"]}],i=[{id:"recruiter",name:"The first reader",role:"Recruiter, sourcer, or whoever opens the link first",time:"30\u201360 seconds",wants:"Who is this, what do they do, are they plausibly qualified, and is this link safe."},{id:"manager",name:"The hiring manager",role:"Engineering manager or tech lead",time:"2\u201310 minutes, if intrigued",wants:"Can this person build hard front-end things? Is the judgement real or is this a stunt?"},{id:"engineer",name:"The interviewer",role:"Whoever runs the loop, skimming beforehand",time:"5 minutes",wants:"Something concrete to ask about. Evidence of method rather than evidence of effort."}],o=[{persona:"recruiter",verdict:"strong",heading:"The banner does its job now",body:`"Short on time? Here's my CV" answers the only question I have in the first second, and the line under it gives me a title and years without a click. The document opens over the page instead of taking me somewhere, which means I never lose my place.`},{persona:"recruiter",verdict:"risk",heading:"Before the page loads, it claims to be Google",body:'The static shell paints the Meet mark and the words "Google Meet" until the script arrives. On a phone on a bad connection that is the whole first impression, and it is the one thing here that could get the link reported rather than merely closed.'},{persona:"manager",verdict:"strong",heading:"The method is the argument, and it holds",body:"Measured rather than eyeballed, with the unmeasurable surfaces labelled as ours. Retractions in the commit log where a diagnosis was wrong. That is a stronger signal than the clone itself: plenty of people can copy an interface, far fewer will write down that their own test was invalid."},{persona:"manager",verdict:"mixed",heading:"The desktop is impressive and unexplained",body:"A working Windows shell inside a screen share is the most technically ambitious thing here. It is also the part where I stop being able to tell what is a CV and what is a demo, and nothing on screen tells me which. Label it and it becomes a highlight instead of a detour."},{persona:"engineer",verdict:"strong",heading:"There is a lot to ask about",body:"Container queries used for an aspect-locked fit, a pure reducer that is unit-tested without a DOM, a size budget failing the build, an SVG letterboxing bug traced to a default. Any of those is a twenty minute conversation."},{persona:"engineer",verdict:"mixed",heading:"I want the failures, not the features",body:"The most interesting page in the project is the one listing the bugs that got past three rounds of testing, and it is buried. Lead with what broke; the working parts speak for themselves."}],s=[{id:"backlog",label:"Backlog"},{id:"doing",label:"In progress"},{id:"review",label:"QA"},{id:"done",label:"Done"}],r=[{id:"T4",col:"done",size:"M",tag:"trust",title:"Say something before the camera prompt",note:"Done, by removing the prompt instead. There is no permission bar left to get in front of \u2014 see T29."},{id:"T5",col:"backlog",size:"S",tag:"trust",title:"Label the emulated browser and desktop",note:"A browser with an address bar drawn inside a page is a phishing pattern. Keep the trick, label it."},{id:"T6",col:"backlog",size:"M",tag:"content",title:"Rewrite the plain CV footer",note:"It closes on build receipts and is no-print, so the PDF loses the disclaimer with it."},{id:"T7",col:"done",size:"S",tag:"content",title:'"Against this job ad" names no job ad',note:"Closed by N66 from the other end: with no code the CV now names the employer, so the section has a job ad to be against."},{id:"T8",col:"review",size:"M",tag:"onboarding",title:"CV opens as an overlay, not a route",note:"Shipped. Meet never navigates away from itself and neither should this."},{id:"T9",col:"review",size:"M",tag:"onboarding",title:"Per-company copy behind a code",note:"Shipped. No employer named by default; ?c= swaps in the specific lines."},{id:"T10",col:"review",size:"L",tag:"specs",title:"Project specifications panel",note:"Shipped. One place the build is documented, reachable from the home screen and from inside the call."},{id:"T11",col:"review",size:"M",tag:"call",title:"Easter eggs open inside the call",note:"Shipped, then QA\u2019d by Nam \u2014 which is where T16 to T20 came from. Join goes straight to the call with the clip playing on the shared screen."},{id:"T12",col:"done",size:"L",tag:"call",title:"The shared desktop",note:"Windows that drag, resize, snap and minimise, a file explorer, a browser and a media player."},{id:"T13",col:"done",size:"M",tag:"call",title:"Pinned and presenting layouts",note:"Read off the live product while a share was running, the only way those states were reachable."},{id:"T14",col:"done",size:"M",tag:"trust",title:"Perception pass",note:"How this reads to a stranger, ranked by how fast it pushes them toward closing the tab."},{id:"T15",col:"done",size:"S",tag:"onboarding",title:"Banner says it is a CV",note:"The first line now answers the category question instead of describing the format."},{id:"T16",col:"review",size:"L",tag:"call",title:"Real video controls on the shared player",note:"Shipped, then cut back on Nam\u2019s note that it obstructed the picture. Clicking the video pauses it; the overlay is now one play button, shown only while paused and for a second after a press. Skip \xB110s is gone \u2014 the clips are 8 to 30 seconds, so it only ever meant the start or the end."},{id:"T17",col:"review",size:"M",tag:"call",title:"The player stops lying about sound",note:"Shipped. It autoplayed muted while showing an unmuted speaker at full volume. The UI now reads off the video, and the visitor\u2019s choice is remembered \u2014 a mute the browser imposed is not saved as one they chose."},{id:"T18",col:"review",size:"S",tag:"call",title:"No share sheet over an easter egg",note:"Shipped. The meeting\u2019s-ready card exists to say the link is copyable; parked over a 30-second clip it is just clutter. Suppressed in the reducer, so a future route into an egg cannot forget."},{id:"T19",col:"review",size:"S",tag:"call",title:"Egg player opens centred",note:"Shipped. It was inheriting the cascade meant for windows you opened yourself and landing in the corner behind Explorer."},{id:"T20",col:"review",size:"S",tag:"call",title:"Leaving an egg goes straight home",note:"Shipped. The ended screen earns its place after a real visit; after a clip it is a speed bump, once per egg, for someone hunting them."},{id:"T21",col:"review",size:"S",tag:"call",title:"BUG: countdown ring animated in two frames",note:'Fixed. A unitless custom property inside calc() stays a <number>, so the keyframe never resolved to a length and Chrome fell back to DISCRETE animation \u2014 full arc for 30s, then none. Nam: "either fully blue or fully white".'},{id:"T22",col:"review",size:"S",tag:"specs",title:"BUG: three CSS rules had lost their selectors",note:"Fixed. A prune deleted the selector lines and left the declarations, which a browser silently discards. deadcss cannot see it \u2014 with the selector gone there is no name left to report \u2014 so css-structure.mjs now gates on it."},{id:"T23",col:"review",size:"S",tag:"specs",title:"BUG: local video could not seek",note:"Fixed. serve.mjs answered Range with a plain chunked 200, so Chrome reported the media unseekable and every skip snapped to zero. Production was never affected, which is exactly why it wasted a QA pass."},{id:"T25",col:"review",size:"S",tag:"call",title:"BUG: speed menu was white on white",note:"Fixed. color:#fff for the closed control inherited into the <option> elements, and the platform draws the popup on its own surface \u2014 which this document forces light. color-scheme:dark plus explicit option colours."},{id:"T26",col:"review",size:"S",tag:"call",title:"BUG: the call auto-ended and dumped you home",note:"Fixed. The ended screen\u2019s 60s auto-return kept ticking after you left it, then dispatched screen: home from under you mid-call. Its guard listened for hashchange, and main.ts navigates with pushState \u2014 which never fires it, so the guard had never once run. Each visit armed another one. The tick now checks it is still the ended screen."},{id:"T27",col:"review",size:"S",tag:"specs",title:"BUG: Meeting tools was wider than every other panel",note:"Fixed. It forced 460px against the 360 every other drawer uses, so it sat over the video tile and the right edge moved depending on which drawer you opened. The width existed because eight tabs would not fit; they wrap to two rows now and there are five, so the cause went with it."},{id:"T28",col:"review",size:"S",tag:"specs",title:"Meeting tools: two tabs removed, five reordered",note:"Removed. The requirement map is already in About and the mock Chrome opens the real posting, three copies is how they start disagreeing. Design went on Nam\u2019s call: not relevant here, and some mystery is worth keeping."},{id:"T29",col:"review",size:"M",tag:"trust",title:"The page never asks for your camera",note:"Shipped. getUserMedia is gone \u2014 the control flips its own icon and nothing else, verified by wrapping mediaDevices.getUserMedia and toggling both ways. Closes R11 in the perception doc, which called the browser\u2019s permission bar on a page dressed as Meet the scariest moment in the funnel."},{id:"T30",col:"review",size:"M",tag:"specs",title:"WebGL effects pipeline deleted",note:"Removed with the camera it ran on: the Effects tab, src/fx/pipeline.ts, the fx side quest, the \u2018e\u2019 shortcut and the Backgrounds button. A real loss \u2014 it was the most technically substantial thing here \u2014 but it was only ever visible to a reader who granted the permission we just removed. Recoverable from git."},{id:"T31",col:"review",size:"S",tag:"trust",title:"BUG: the lobby named a camera it never asked about",note:'Fixed. The lobby promoted a chip to "Integrated Camera", a hardcoded device name, in a file whose own comment forbids exactly that. It only looked right because Windows calls most built-in webcams that. Now reads "No camera requested" beside "Effects unavailable", matching the mic and speaker chips, and the promote mechanism is gone because nothing can be granted.'},{id:"N1",col:"done",size:"M",tag:"onboarding",title:"Join the interview already sharing, Chrome centred, CV open",note:"The default state of the interview call should be presenting full screen with the mock Chrome centred on the CV.",detail:{why:"The call currently opens on an empty tile. The first thing a reader should see is the work, not a placeholder avatar.",done:["Joining the interview meeting starts a share automatically","The mock Chrome opens centred, not cascaded","It shows the same CV document the home screen\u2019s Open document shows"],raised:"Nam, QA 27 Aug, point 1"}},{id:"N2",col:"done",size:"S",tag:"call",title:"Window share offers Chrome, not Explorer",note:"Sharing a window offers the file explorer, where there is nothing to look at. It should offer the browser with its tabs.",detail:{why:"Window mode is a single window on nothing. Explorer is a file list; Chrome carries the actual content and its tab strip can hold every document at once.",done:["The Window tab of the share picker offers the browser","Its tab strip shows the documents instead of one tab per share source"],raised:"Nam, QA 27 Aug, point 2"}},{id:"N3",col:"done",size:"M",tag:"content",title:'"Things I built", merged, with real itch.io games',note:"Four things I built becomes Things I built, absorbs the other list, and links actual games rather than a bare profile URL.",detail:{why:"Two lists answering one question, and a link to a profile page asks the reader to do the browsing.",done:["One list, titled Things I built","Named games from southocean.itch.io with links","Graphics or at least a per-game line, not just the profile link"],raised:"Nam, QA 27 Aug, point 3",notes:"Source: https://southocean.itch.io/"}},{id:"N4",col:"done",size:"S",tag:"content",title:"Use the real Mahjong product, not a hand-drawn board",note:"The riichi board is sloppy and not up to code. Point at the real client instead.",detail:{why:"A badly drawn mahjong board on the CV of someone who builds mahjong clients is the worst possible advert.",done:["The riichi page frames or links preview.mahjongstars.com","The hand-drawn board is gone"],raised:"Nam, QA 27 Aug, point 4",notes:"https://preview.mahjongstars.com/, public, so disclosing it is fine."}},{id:"N5",col:"done",size:"S",tag:"onboarding",title:"Home screen copy: subtitle and the meeting note",note:"Two lines, both rewritten to Nam\u2019s wording.",detail:{done:['Subtitle: "Lead front-end developer, 7 years \xB7 Agentic programming wizard \xB7 PhD in going the extra miles"','Meeting note: "Get personal with Nam in this interactive CV. Only if all meetings could be like this!"'],raised:"Nam, QA 27 Aug, point 5"}},{id:"N6",col:"done",size:"S",tag:"content",title:"The contacts list: Diep Bui, no references, new search label",note:"Trim the referral picker to the one real contact.",detail:{done:['"Diep, referral" becomes "Diep Bui"',"Both Reference rows deleted",'Search placeholder becomes "Search my referral"'],raised:"Nam, QA 27 Aug, point 6"}},{id:"N7",col:"done",size:"S",tag:"content",title:"The Diep Bui card, and no work email anywhere",note:"Retitle the card, replace the calling-as line with a joke, and purge the work address from the whole site.",detail:{why:"The work email is Nam\u2019s current employer address and has no business on a job application.",done:['Card title: "Diep Bui, referral"','The "Calling as" line replaced with something playful',"The description line is less stiff","The work address appears nowhere in src/ or docs/ \u2014 asserted by a test"],raised:"Nam, QA 27 Aug, point 7"}},{id:"N8",col:"done",size:"S",tag:"content",title:"Loosen the Calls page copy, and drop the referral note",note:"One of the two lines should be playful, and the referral note goes, here and on the ended screen.",detail:{why:'Nam: "In general Idk if a referral note is really needed at all."',done:["Second line on the Calls page is playful rather than professional","The referral note is gone from the Calls page","It is gone from the ended screen too"],raised:"Nam, QA 27 Aug, point 8"}},{id:"N9",col:"done",size:"S",tag:"specs",title:"Board cleanup, and take up T7",note:"T1 and T2 off the board, T4 to done, T7 becomes the job-requirement section gated behind ?c=.",detail:{done:["T1 and T2 removed","T4 moved to done",'T7 actioned as "Against the job requirement", only rendered with a company code'],raised:"Nam, QA 27 Aug, point 9"}},{id:"N10",col:"done",size:"S",tag:"specs",title:"Rename to Project spec, drop the work-authorisation review",note:"The full name is too long, and one design-review point is wrong.",detail:{why:'Nam: "Any recruiter will know uppsala and stockholm are very close and I absolutely can work in sthlm. Meaningless point."',done:['Panel title reads "Project spec"','The "CV does not say I can work here" review is deleted',"T3 comes off the board with it"],raised:"Nam, QA 27 Aug, point 10"}},{id:"N11",col:"done",size:"S",tag:"specs",title:"Timeline: hide the near-empty days",note:"22 and 24 August had 1 and 0 commits and clutter the chart.",detail:{done:["Those two days are not drawn","The totals still include them"],raised:"Nam, QA 27 Aug, point 11"}},{id:"N12",col:"done",size:"S",tag:"specs",title:"Overview: one type size, shorter, better subtitle",note:"The first two paragraphs render at different sizes, the prose is long, and the panel subtitle says nothing.",detail:{done:["Both opening paragraphs share one style","The prose is shorter",'Subtitle: "One week, one agent, one interactive CV."'],raised:"Nam, QA 27 Aug, point 12"}},{id:"N13",col:"done",size:"M",tag:"specs",title:"Overview holds the timeline; content is about the project only",note:"Merge the Timeline tab in, drop Method, and stop rendering Nam\u2019s personal skills in a panel about this repository.",detail:{why:'Nam: "this is project spec - everything in here is about this project. The C++ and React are not relevant here."',done:["Commit chart at the top of Overview","Milestones at the bottom, spread horizontally with dates","Timeline tab gone","Method section gone","Stack lists what this build uses, not what Nam knows"],raised:"Nam, QA 27 Aug, point 13"}},{id:"N14",col:"done",size:"S",tag:"specs",title:"Clicking the dimmed ground closes Project spec",note:"Same contract as the close button.",detail:{done:["A press on the scrim closes the panel","A press that starts inside the card and drifts out does not"],raised:"Nam, QA 27 Aug, point 14"}},{id:"N15",col:"done",size:"S",tag:"content",title:"The CV socials become icons",note:"GitHub, LinkedIn and itch.io are already links; they should be icons.",detail:{done:["Each social is an icon linking to its destination","Each has an accessible name"],raised:"Nam, QA 27 Aug, point 15"}},{id:"N16",col:"done",size:"S",tag:"content",title:"BUG: email and location are oddly indented on the CV",note:"The contact block does not line up with the rest of the document.",detail:{raised:"Nam, QA 27 Aug, point 16"}},{id:"N17",col:"done",size:"M",tag:"content",title:"Wasabi Productions, and four rewritten bullets",note:"Mahjong Logic becomes Wasabi Productions, and the role bullets are replaced.",detail:{why:"The company has a landing page now, and the React + Unity hybrid is no longer what the product is.",done:["Mahjong Logic \u2192 Wasabi Productions everywhere","No React + Unity hybrid claim anywhere in the CV","Platform bullet: web app, to Unity, to React Native for web and app","Team-of-five bullet replaced with the agentic-programming one","Third bullet: feature design, UX, responsive, 4\u20135 Dan bot, bot swarm controller, automated QA","Fourth bullet: designers, backend, marketing and investors; vertical grasp; decides feature priorities"],raised:"Nam, QA 27 Aug, point 17"}},{id:"N18",col:"done",size:"S",tag:"content",title:"Merge the two labs into D&A Research",note:"InfoLab and MSO Lab become one entry with only the highlights.",detail:{done:['One entry, "D&A Research"',"Graph mining, part of the Multinet library. InfoLab, Uppsala University, 2018","Sensor network optimisation: two publications, one book chapter, one best-paper award. MSO Lab, HUST, 2014\u20132017"],raised:"Nam, QA 27 Aug, point 18"}},{id:"N19",col:"done",size:"S",tag:"content",title:"Bkav wording",note:'"Delivered a beta meeting the relevant ISO standards" \u2192 "Delivered a beta version meeting the relevant ISO standards".',detail:{raised:"Nam, QA 27 Aug, point 19"}},{id:"N20",col:"done",size:"S",tag:"content",title:'"Against this job ad" \u2192 "Against the job requirement"',note:"And it only renders with a company code.",detail:{raised:"Nam, QA 27 Aug, points 9 and 20"}},{id:"N21",col:"done",size:"M",tag:"content",title:"Restructure the skills block",note:"Two columns, no duplicates, and a stronger test-automation line.",detail:{why:'Languages were being listed twice, once by name and again under "over 10,000 lines", and the bot-controller line undersells the testing work.',done:["Left column: skills and frameworks. Right column: languages","Frameworks: React, Unity, Flutter","Test automation: 75\u201390% unit coverage, AI-assisted, automated QA of core UI flows","The WebGL / effects-pipeline skill is deleted","No language appears twice"],raised:"Nam, QA 27 Aug, point 21"}},{id:"N22",col:"done",size:"M",tag:"content",title:"Off the clock, rewritten; honours removed",note:"Specific credits instead of vague instincts.",detail:{done:["Honours section deleted",'The "Not filler" line deleted',"Stand-up: Fyris Komedi, Comedy Nation, Uppsala Roligaste 2026","Acting: Tomma H\xE4nder (.MOV Filmfestival 2026), The Darkest Hour, Don\u2019t Cry Over Spilled Milk","SFX artist removed","Zombie walk: website, marketing, makeup, logistics; featured on SVT and UNT, with a link","Sports as its own line: swimming and Brazilian jiu-jitsu"],raised:"Nam, QA 27 Aug, point 22"}},{id:"N23",col:"done",size:"S",tag:"content",title:"Trim the CV footer",note:"The build receipts and the Google disclaimer are not doing work on the document.",detail:{done:["Build/size/dependency line removed","The not-affiliated paragraph removed","The print hint kept if it still earns its place"],raised:"Nam, QA 27 Aug, point 23"}},{id:"N24",col:"done",size:"L",tag:"onboarding",title:"The guided tour: captions, an on-screen cursor, and an adaptive script",note:"The big one. A scripted walkthrough that narrates itself, moves a cursor in sync, and adapts when the visitor takes over.",detail:{why:"Everything else on this board makes the CV better to read. This makes it a demo that runs itself, which is the difference between a page a recruiter skims and one they watch to the end.",done:["Captions on by default in the green room","The share sheet auto-closes after 8s, with a visible countdown that pauses on hover",'Captions drive the demo: saying "let us look at the CV" opens it',"An on-screen cursor represents Nam and moves in sync with the captions","Clicking anything switches the script to commentary mode for that part, then resumes","A queue of visitor actions, with commentary shortened as it grows","Too many queued actions: acknowledge it, hand over, end the captions politely","A planning doc, QA\u2019d three times before implementation, then the feature QA\u2019d against the doc"],raised:"Nam, QA 27 Aug, point 24",notes:"Script parts are prioritised so a shortened run still covers the important ones. Two modes: active showcase and passive commentary; the hard part is guessing intent when the visitor takes over."}},{id:"N25",col:"done",size:"M",tag:"specs",title:"Kanban cards open a ticket",note:"Shipped first, so the rest of the QA list had somewhere detailed to live.",detail:{why:'Nam: "That would keep the board itself clean and not bloated, cause all the details are in the ticket popup view."',done:["A card opens a ticket on click, Enter or Space","The ticket holds why, done-when, who raised it and notes","Escape and a press on the dimmed ground close it","Focus returns to the card"],raised:"Nam, QA 27 Aug, point 25"}},{id:"N26",col:"done",size:"L",tag:"specs",title:"A script editor for the guided tour",note:"A page showing every script branch, where they converge, and the safe jump points.",detail:{why:'Nam: "This would be incredibly helpful in tweaking and redesigning the caption script if needed." The tour in N24 is only maintainable if its branching is visible.',done:["Every script part is listed with its branches","Convergence points are shown","Safe jump points are marked"],raised:"Nam, QA 27 Aug, point 26",notes:"Depends on N24 landing first: there is no script tree to draw until there is a script tree."}},{id:"N27",col:"done",size:"M",tag:"onboarding",title:"Do not join already sharing",note:"N1 is reverted. The share is something the tour performs, not the state it starts in.",detail:{why:'Nam: "when joining the call, we shouldnt start in screen sharing. Screensharing should be triggered by caption script, so we can feature full feature of the CV." Landing mid-share skips the part that makes the demo land, watching someone share a screen is the familiar bit that earns the strange bits.',done:["An ordinary join opens on the call, not on a share","The easter-egg boot still opens already sharing, because that clip is the whole meeting","The tour's first act performs the share itself"],raised:"Nam, QA 27 Aug, point 1",notes:"N1 shipped the opposite of this and was right at the time, the reader landed on the work instead of an avatar. What changed is that there is now a tour to do the landing for them. QA in a browser: an ordinary join opens on the call, and the first act performs the share."}},{id:"N28",col:"done",size:"L",tag:"onboarding",title:"A real mouse pointer, moving like a hand",note:"The blue dot becomes an arrow, and it travels, overshoots, settles and fidgets instead of teleporting.",detail:{why:`Nam: "the mouse should have a mouse icon not the blue dot cause it forces user to learn something they dont need to... as if this is a regular person using the computer. It's very trippy yes but thats exactly what I want. It's a mixture of familiarity + strange." A blue dot is a new symbol to decode. An arrow is one everybody already has.`,done:["A real cursor arrow, drawn to match the platform's","Travel time from Fitts's law, not a fixed duration","A curved path with an overshoot and a corrective submovement","Tremor while idle, and an occasional drift","A visible press on click, and a dwell before it","It owns the whole screen, not just the shared surface"],raised:"Nam, QA 27 Aug, point 2",notes:"Human pointing is ballistic then corrective: one fast movement that covers most of the distance and overshoots, then slower closed-loop corrections under visual feedback. Copying that shape is most of what makes a synthetic cursor read as a hand. QA in a browser: 5404px of travel across one full run, arcing, overshooting and settling on every target."}},{id:"N29",col:"done",size:"M",tag:"onboarding",title:"The share is performed: captions, picker, Entire Screen, full screen",note:"The cursor does every step a person would do, in order, with nothing skipped.",detail:{why:'Nam: "if CC was not on, then the mouse would move to click on CC to enable it, then the script starts. Then on cue to share screen, mouse will move to the screensharing button, then to full screen, then so on."',done:["Captions are switched on by the cursor when they are off, before the first line","Share screen opens the real picker","Entire Screen is selected, then Screen 1, then Share","The browser window is maximised inside the shared desktop","Every step is a real click on a real control, not a shortcut into state"],raised:"Nam, QA 27 Aug, points 1 and 2",notes:"QA in a browser: captions, picker, Entire Screen, Screen 1, Share, launch Chrome, maximise, every step a real press on a real control."}},{id:"N30",col:"done",size:"S",tag:"content",title:"Rewrite the opening",note:"Shorter, warmer, and it hands the visitor a goal before it starts talking.",detail:{why:'The old opening explained the format. "a working rebuild of the Meet web client", which is the least interesting true thing about it. Nam\u2019s version says hello, offers a game, and moves.',done:['"Hi, I\u2019m Nam. Thank you for joining me here."','"Let me walk you through my world."',"The achievement count is named, and it is the real one",'"First, let\u2019s share my screen" is the cue for the share'],raised:"Nam, QA 27 Aug, point 3",notes:"The count is asserted in the test suite against the quest list, so the line cannot quietly become a lie. The count is asserted against the quest list in the test suite, so the line cannot go stale."}},{id:"N31",col:"done",size:"L",tag:"onboarding",title:"The CV act: lines tied to scroll, not to a stopwatch",note:"The cursor scrolls the document and each section speaks as it arrives. Scroll past it and the short version plays.",detail:{why:'Nam: "all these texts should have trigger in the CV as we scroll, and they should be queued so that each line has its reading time. If we scroll past a point quickly then we run the short version of the lines to speed it up."',done:["Each line is anchored to a section of the document","The cursor scrolls; arriving at a section speaks it","A section reached early plays its short version","A section already passed is not replayed","Leaving the CV entirely cuts the losses rather than finishing the script"],raised:"Nam, QA 27 Aug, point 4",notes:"QA in a browser: the CV scrolled 1473px across seven anchored lines."}},{id:"N32",col:"done",size:"M",tag:"onboarding",title:"Restlessness, and the bar that flashes when it moves",note:"Score the visitor\u2019s impatience, and show the score only at the moment it changes.",detail:{why:`Nam: "we should score user on their reading speed and restlessness. The higher they score, the more escalated our acknowledgements would be. Let's flash a restlessness bar somewhere on the screen whenever this bar gets increased, only at the moment of the increase, then it fades away."`,done:["A 0..1 restlessness score with named tiers","It rises on fast bails, scroll speed and click bursts, and decays on dwell","Acknowledgements are drawn from a pool matched to the tier","The same acknowledgement is never used twice in a run","A bar appears on increase, holds, and fades","Nothing is shown while it is merely decaying"],raised:"Nam, QA 27 Aug, point 4",notes:"QA in a browser: the meter stepped 28 \u2192 42 \u2192 56 \u2192 70% through a click burst and hid itself afterwards."}},{id:"N33",col:"done",size:"L",tag:"specs",title:"The visitor profile, a know-your-user model",note:"One pure module that watches what the visitor does and says what they seem to want.",detail:{why:'Nam: "Feels like we are essentially building a know your user system, like user profiling. Let me know what else we can add to this system to get a clear image of user intention and interest, so we tailor our script to their interest and in their own pace."',done:["Signals: idle time, click rate, scroll speed, dwell per section, bail rate, backtracking, revisits, depth of navigation, input modality","Derived: reading speed, restlessness, engagement, and an interest ranking over the parts","Pure and unit-tested, no DOM, no timers","The director asks it for pace and register rather than guessing"],raised:"Nam, QA 27 Aug, point 4",notes:"Kept pure for the same reason the tour director is: adaptivity is the part most likely to be subtly wrong and least likely to be noticed. Nineteen unit tests over the model. The two strongest signals turned out to be scroll speed and revisiting, dwell cannot tell reading from having walked away, and a revisit is the only signal that costs the visitor effort."}},{id:"N34",col:"done",size:"M",tag:"content",title:"The desktop is commentary, not narration",note:"Nothing introduces the shared desktop. It answers back when you touch it.",detail:{why:'Nam: "nothing to introduce here, its self explanatory. This is more a commentary when player gets curious and clicking around... Short and punchy, so we can go back to whatever we were talking about."',done:["The desktop part leaves the primary flow","Quips on drag, snap, minimise, the clock, the calendar, wifi and the tray","Each quip fires once and is never cycled back","The brief line stays as the first thing said"],raised:"Nam, QA 27 Aug, point 5",notes:"QA in a browser: the Start-menu quip fired once and stayed quiet on the second press."}},{id:"N35",col:"done",size:"S",tag:"content",title:"Wasabi: the pap-pap-pap rewind",note:"Scroll past seven years of work in under three seconds and the tour scrolls you back.",detail:{why:'Nam: "I really want to get playful here... Pap pap pap.. 7 years of my life is only worth 3s of your time? Come back! Then we scroll up to the top of the page. Then we go Just kidding and scroll back to the place it was triggered."',done:["A bail under three seconds triggers it","The document scrolls back to the top",'"Just kidding", and it returns to exactly where it was',"The scroll position is remembered, not guessed","It fires at most once"],raised:"Nam, QA 27 Aug, point 6",notes:"QA caught it firing at the tour itself: a programmatic scrollTop dispatches a scroll event indistinguishable from a wheel, and isTrusted does not separate them, the browser marks scroll events trusted whoever caused them. The hand rolled to the Wasabi years and then accused the visitor of skipping them."}},{id:"N36",col:"done",size:"M",tag:"content",title:'"How this was built" opens the real page',note:"The mock browser\u2019s tab was a stale drawing. It shows the document the home screen shows.",detail:{why:'Nam: "Oh damn this page is outdated! We actually have a how this was built page that we show in home screen. We need to show that here in the mock browser." Two copies of the same document is how they start disagreeing, and this pair already had.',done:["The tab frames the real built document","The tour navigates to it rather than cutting to it","Banter as the tabs are flipped, one-shot"],raised:"Nam, QA 27 Aug, point 6b",notes:"QA in a browser: the tab is in the default strip, the tour opens it, and it frames the real document rather than a second drawing of it."}},{id:"N37",col:"done",size:"S",tag:"content",title:"Accessibility and tests leave the main flow",note:"They only speak when the visitor opens them.",detail:{why:'Nam: "Accessibility and tests are not in the main flow, only triggered when user actually navigate to these in the right panel... look, the CV is the main part and the rest should probably be all commentary, short and punchy."',done:["Neither is reached by the script","Both keep a commentary register on their triggers","The primary flow gets shorter, which is the point"],raised:"Nam, QA 27 Aug, point 7",notes:"Neither is reachable from the script any more. Both kept their commentary."}},{id:"N38",col:"done",size:"M",tag:"content",title:"The personal story, and the questions it answers",note:"One uninterrupted segment on sufficient downtime, answering what a hiring manager actually wants to ask.",detail:{why:'Nam: "we have some personal storytelling that is triggered during sufficient down time, ideally after we have introduced all the fun part, and once triggered it will run uninterrupted. This will answer the core questions that a hiring manager would have."',done:["Runs only after the flow has covered the demonstrable parts","Runs only after real downtime, not after a pause","Uninterruptible once started, except by Stop","The questions it answers are listed in the script editor beside it"],raised:"Nam, QA 27 Aug, point 7",notes:"QA caught it starting four seconds after the goodbye: silence was measured from the last INPUT, and a visitor who has touched nothing has been silent all along. It is measured from the later of the last input and the flow ending now."}},{id:"N39",col:"done",size:"S",tag:"trust",title:'BUG: "The posting, line by line" renders empty',note:"The tab in the shared browser shows a heading and a note and nothing else.",detail:{why:'The requirement map is gated on a company code, and the deployed link carries none, so a tab titled Google Careers opened onto an apology. Nam: "this page is empty? It was fine before."',done:["The mapping renders without a company code","The heading names which posting it is measured against","The gate stays where it is genuinely needed"],raised:"Nam, QA 27 Aug, point 8",notes:"T7 put the gate there for a real reason, measuring a reader against a posting their company never advertised. The tab is Google-branded either way, so the honest fix is to name the posting rather than hide the answer. QA in a browser: the mapping renders with no company code, under a heading that names which posting it is measured against."}},{id:"N40",col:"done",size:"M",tag:"content",title:"The job-requirement act, bridged straight off the CV",note:'"So how do these score against the job requirement? I\u2019ve got you covered." Then it goes and shows you.',detail:{why:'Nam: "Oh damn I completely forgot the part against the job requirement!... then navigate to the google career tab, then slowly scroll through everything with playful commentary." It is the single most load-bearing screen for the actual reader and it was not in the script at all.',done:["The act follows the CV with no seam","The cursor opens the Careers tab and scrolls it","Requirement-by-requirement banter, escalating",'"And you get a check. And everybody gets a check."'],raised:"Nam, QA 27 Aug, point 8",notes:"QA in a browser: the act bridges off the CV with no seam and scrolls the posting 926px."}},{id:"N41",col:"done",size:"M",tag:"call",title:"Off the clock: play the clips they have not found",note:"Track which eggs the visitor has seen and walk them through the remainder.",detail:{why:'Nam: "here we need to track which of the easter eggs they have found, then we walk them through the rest, earning them the remaining achievements."',done:["Seen clips are remembered across visits","The act plays only the ones still unseen","It says what it is playing and why","It closes on the corny line, and calls itself corny"],raised:"Nam, QA 27 Aug, point 9",notes:'QA in a browser: three unseen clips played, and a second run said "\u2026which you have already found. All of them.", so the record survives a reload.'}},{id:"N42",col:"done",size:"S",tag:"content",title:"The close has to close",note:"Say the tour is over, hand the machine back, thank them.",detail:{why:'Nam: "VERY IMPORTANT! Signal to them that this is the end of the tour, they are free to explore the rest, thank them for their time." A demo that just stops talking leaves the visitor waiting for the next line instead of exploring.',done:["It says, in words, that the tour is finished","It says what is left to look at","The cursor leaves the screen rather than parking on a control","Thanks, once, and without a pitch attached"],raised:"Nam, QA 27 Aug, point 10",notes:"QA in a browser: it says in words that the tour is finished, and the hand leaves the screen."}},{id:"N43",col:"done",size:"M",tag:"specs",title:"The script editor separates flow from commentary",note:"Two lists, not one: what the tour will say, and what it only says back.",detail:{why:'Nam: "the scripts, I want to see the separation between the primary flow, vs what we do only as commentary." With commentary mixed into the same list there was no way to read the running time of the actual demo.',done:["The primary flow is listed in order with a running time","Commentary quips are listed separately, by trigger","The acknowledgement pool is shown by tier","The hiring-manager questions are listed beside the story segment"],raised:'Nam, QA 27 Aug, point 10 ("add all of these to the kanban board")',notes:"Two lists. The flow has a running time that means something for the first time, because throwaway lines stopped counting toward it."}},{id:"N44",col:"done",size:"M",tag:"content",title:"It is a conversation, not a tour",note:"Rename it everywhere the visitor can see, because the word was shaping the writing.",detail:{why:'Nam: "I actually dont like that it was a tour, no this is a real attempt at talking to the user." The word was not only in the labels. It was in the prose, and a script that thinks of itself as a tour writes lines that introduce sections instead of lines that talk to somebody.',done:['No visitor-facing string says "tour"',"The Stop control says what it actually stops","The achievement and its hint are about hearing him out, not about a walkthrough","The Scripts panel describes one script, not a tour script plus a loop"],raised:"Nam, QA 27 Aug, second pass",notes:"The internals keep the tour/ directory and the TourState type: renaming a pure module nothing reads out loud costs a diff and buys nothing. The line between them is whether a stranger can see the word."}},{id:"N45",col:"done",size:"M",tag:"content",title:"Fold the caption loop into the one script",note:"Line by line, on Nam\u2019s own call: keep, merge, drop, rewrite.",detail:{why:"Two scripts on one surface meant the better-sounding one only ever played when nobody was being talked to. The verdict column in the Scripts panel existed to make the merge decidable; this is the merge.",done:["Lines 0 and 1 open the conversation, before the share","Lines 3 and 4 merged into the current-position segment; line 2 dropped as a duplicate","Line 5 dropped, line 10 dropped","Lines 6 and 7 kept, with the award replaced by the book chapter","Line 8 dropped as a duplicate; line 9 kept and placed in the build segment","The standalone loop is gone, and nothing plays behind the script any more"],raised:"Nam, QA 27 Aug, second pass",notes:'Line 7 was "a best-paper award" and is now the book chapter, on his instruction. Both are in the CV; the chapter is the less familiar claim and the harder one to have made up.'}},{id:"N46",col:"done",size:"L",tag:"call",title:"The script has a clock, and a click moves it",note:"Every line carries the second it is due. A trigger cuts the current segment short instead of queueing behind it.",detail:{why:'Nam: "timestamp when the text is shown, and what mouse event it triggers, which would also work the other way around." Without a clock there was no way to say how long the conversation is; without the fast-forward, clicking ahead meant waiting for the segment you had just left to finish talking.',done:["Every flow line has a derived timestamp, shown in the Scripts panel","The panel states the total running time from the same numbers","A visitor trigger cuts the current segment at the line it is on","The cut segment counts as covered, so it is not re-narrated later","The timestamps are derived, not authored, so they cannot drift from the dwells"],raised:"Nam, QA 27 Aug, second pass",notes:"Derived rather than authored on purpose. An authored `at` beside an authored `ms` is two sources of truth for one fact, and the panel exists to be trusted."}},{id:"N47",col:"done",size:"L",tag:"call",title:"Captions arrive word by word",note:"Typed out rather than pasted, paced by punctuation. Click to see the whole line.",detail:{why:'Nam: "I want to display word by word kinda similar to how its capturing real human voice." A whole sentence appearing at once is a subtitle file; live captions arrive as the words do.',done:["Words appear one at a time, paced by length and punctuation","A comma rests shorter than a full stop, and an em dash longer than either","The screen-reader announcement is the authored line, once, not a word at a time","Reduced motion shows the whole line at once","A press on the bubble, or on the empty stage, completes the line"],raised:"Nam, QA 27 Aug, second pass",notes:"The hesitations Nam also asked for shipped with this and were then removed, see N53. The reveal itself was never the problem."}},{id:"N48",col:"done",size:"M",tag:"trust",title:"The caption holds for as long as you need it",note:"A filling ring on the bubble. Hover pauses it, a press skips it.",detail:{why:'Nam: "player can read fast, slow, whatever and we can accommodate for it." Authored durations are a guess at one reading speed. This makes the guess a default rather than a rule, which is an accessibility fix wearing a game mechanic\u2019s clothes.',done:["The end screen\u2019s ring motif is reused rather than a second progress idiom invented","The ring fills over the line\u2019s authored dwell and advances at full","Hovering the caption pauses the ring, leaving restores it","A press on the bubble or the empty stage advances immediately","The same mechanism drives every line, so nothing is on a separate clock"],raised:"Nam, QA 27 Aug, second pass",notes:"The dwell became the only clock the script runs on, which is why N46 could derive a timeline from it at all."}},{id:"N49",col:"done",size:"M",tag:"content",title:"Post-conversation banter, and then real silence",note:"Why are you still here. Spacing out, under two minutes, with an achievement for sitting through it.",detail:{why:'Nam: "There is nothing more to see here. I swear ... some more stuff like this, spacing out more and more, but no longer than 2min." The goodbye is the correct place to stop talking, so anything after it has to earn the attention, which is exactly what a joke that keeps getting further apart does.',done:["The gaps grow, and the whole outro fits inside two minutes","Sitting through all of it unlocks a secret achievement","It ends with a real goodbye and thanks","The hand turns the captions off, mirroring the press that turned them on","Any input abandons it without penalty"],raised:"Nam, QA 27 Aug, second pass",notes:'Secret rather than listed. A hint reading "sit still for two minutes after the end" spoils the joke and reads as a chore; the other three secrets are hidden for the same reason.'}},{id:"N50",col:"done",size:"S",tag:"specs",title:'BUG: "How this was built" was a second copy of the spec',note:"The browser tab now opens the Project spec itself, tabs and all.",detail:{why:'Nam: "how this was built was still the wrong page, it should open the project spec that we are already showing in home screen." The tab rendered buildDoc() alone, which is one section of the spec\u2019s Overview, so the shared screen showed a document that looked like the spec, was missing four of its five tabs, and could drift from it.',done:["The tab renders the same tabbed spec the home screen opens","One component, two hosts: a dialog from the chrome, a page inside the share","The script segment about the build still scrolls and still lands"],raised:"Nam, QA 27 Aug, second pass",notes:"Extracted rather than duplicated. The dialog keeps the focus trap and the scrim; the page gets the body and nothing else, because a modal inside a fake browser window would trap focus in a screenshot."}},{id:"N51",col:"done",size:"M",tag:"call",title:"Time the interview, and say so at the end",note:"The clock runs from the first line to the goodbye. The outro does not count.",detail:{why:'Nam: "I want to capture the time user spent on the call such that they finish the whole conversation. This is to add gamification to this CV which is my expertise." It also makes the derived timeline of N46 checkable against reality rather than only against itself.',done:["The clock starts on the first spoken line and stops at the goodbye","The outro is excluded, so banter cannot inflate it","Only a run that heard the whole conversation is recorded","The ended screen reports the time, and the personal best beside it","Nothing leaves the machine"],raised:"Nam, QA 27 Aug, second pass",notes:"The personal best is in localStorage next to the quests. Comparing against the derived benchmark is the interesting number: skipping every line with a press is genuinely faster than the authored clock."}},{id:"N52",col:"backlog",size:"L",tag:"trust",title:"A leaderboard for the interview time",note:"Wanted, and blocked on a promise this build makes in four places. The bot-manager server is the wrong shape for it.",detail:{why:'Nam: "Would be awesome if we have a way to have a leaderboard here, who is fastest to complete the interview LOL." And there is real depth under the joke: fast-forwarding lines, and triggering a segment early so the one before it gets cut, are both genuine strategies that lower the total.',done:["A decision on the no-backend promise, made deliberately rather than by accident","If it ships: a submit that is opt-in, carries no identifier the visitor did not type, and is rate-limited","If it ships: the four places that promise no backend are corrected in the same commit"],raised:"Nam, QA 27 Aug, second pass",notes:'Blockers, in order of how hard they are to argue with. (1) The page states "no analytics, no third-party requests and no backend" on the ended screen, in the meeting-ready card, in the Project spec and in the README, a leaderboard makes all four false, and for a CV about trustworthy engineering that is a worse trade than the feature is worth. (2) The CSP is connect-src \u2018self\u2019 with no exceptions, so any host would have to be named in the policy, which is exactly where a reader looks to check claim (1). (3) A public leaderboard on a job application collects timings from named hiring managers, which is a data question rather than a feature question. (4) The bot-manager server is on the React client: a different origin with a different lifetime, and if it stops the CV becomes a site with a broken widget on it. If it ships at all it wants a separate endpoint the CV can lose without noticing, and the honest version is a local personal best, which is what N51 shipped.'}},{id:"N53",col:"backlog",size:"S",tag:"content",title:"REVERTED: the hesitations placed themselves before the punchlines",note:'Automatic placement is out. Where an "uh" goes is a writing decision, and it is waiting on Nam.',detail:{why:'Nam asked for "a little uh, ah, and stuff that would be in a normal casual speech", and the first attempt derived the placement from the text: clause boundaries, a rarity gate tuned by counting against the real script, three separate hashes so nothing correlated. It produced exactly two hesitations in thirty-four lines, always in the same place, costing the line no time, and both of them landed immediately before a punchline. Nam: "they are pausing right before the punch line!?! How the heck is that good?"',done:["The automatic insertion is gone, and the dimmer style with it","The seven tests that measured its rate, determinism and variety are gone","The word-by-word reveal, the dwell ring and the press-to-skip are untouched","Placement, when it returns, is authored per line rather than derived",'And it stays a rendering concern: no "uh" in data/tour.ts'],raised:"Nam, QA 28 Aug",notes:"The lesson is not that the rate was wrong, the rate was right, and a test asserted it. A clause boundary near the end of a sentence is exactly where the setup hands over to the joke, so the better the gate got at finding natural pauses, the more reliably it found the one place a stumble must never go. Punctuation is all an algorithm can see; where the joke is lives in the meaning, and the writer is the only one holding that. A counting test cannot catch this: it will green-light every instance of a thing happening in the worst possible place."}},{id:"N54",col:"done",size:"M",tag:"trust",title:"The CV always opens as an overlay",note:"Four of the five ways in were routing to it instead, which replaced the whole screen.",detail:{why:'Nam: "Everytime we open the CV it should match the same way we show the CV in the home screen: a popup screen, not full screen ... I want you to run a check through out this site." Only the home screen used the overlay; everywhere else dispatched the #plain route, which is the one thing this build claims it never does, since Meet does not navigate away from itself.',done:["The ended screen, Host controls, the Explorer fallback and the D shortcut all open the overlay","The #plain route is untouched: recruiters are sent there and the overlay frames it","Project spec openers were already correct, all four go through openDev()","Verified in a browser from all five entry points"],raised:"Nam, QA 28 Aug",notes:'The audit turned up a quest that had stopped being reachable properly: "plain" unlocked inside the route, so the home screen overlay never counted it. One registration in main.ts now decides what opening the CV means, wherever it happens.'}},{id:"N55",col:"done",size:"M",tag:"call",title:"A line with a mouse interaction is a cutscene",note:"It cannot be skipped past its beat. The hand hurries instead.",detail:{why:'Nam: "we cannot skip the line past getting these interactions, cause otherwise we lose the trigger and the mouse is frozen forever ... So mouse interactions are kinda like cutscenes that you cant skip xD." A correctness fix rather than a nicety: the beats are what make the rest of the script possible, and every later segment declares what it needs.',done:["The caption locks for the duration of a beat, and a press cannot end the line","A press still completes the words, and is remembered so the line ends the instant the beat does","A press during a beat makes the hand move at a third of the time","The press is swallowed rather than passed to the app while locked","Verified by pressing 32 times through the share: it still completed, all five tabs opened"],raised:"Nam, QA 28 Aug",notes:"Three bugs found in QA, all ordering. The lock was taken before the line was spoken, and speaking a line clears the lock, so it locked nothing. The press was absorbed by the caption and then passed on to the page anyway, which dismissed the share picker: the very press meant to hurry the share was cancelling it. And awaiting the line and the beat together deadlocked, because the line cannot resolve until unlock and unlock came after both."}},{id:"N56",col:"backlog",size:"M",tag:"call",title:"The hand should open the easter-egg clips",note:"They currently appear on their own, which is the one place the illusion drops.",detail:{why:'Nam: "when you are showing the easter eggs, you just auto triggering the videos - I dont like that. We should do that with the mouse interaction to keep it consistent. The mouse will open the video, so its really like a real human to the very end." He is right, and it is the same principle as N29: the share is performed through its own four presses rather than switched on, and this is the last thing in the script that cheats.',done:["The hand opens the Explorer window if it is not already up","It finds the row for that clip and opens it the way a person would","The player window opens through the desktop rather than by rebuilding the share","A clip whose row cannot be found is skipped silently, like any other missing beat"],raised:"Nam, QA 28 Aug",notes:"Not started, and deliberately not half-started. The pieces are in place: the Explorer already lists one row per clip (share.ts, kind: video, tab: vid:<id>) and opening one routes to the player window, so the beat is a press on a row rather than new machinery. What makes it more than a one-liner is that playEgg currently REBUILDS THE WHOLE SHARE with the clip booted, which tears down the desktop the hand is standing on. It wants to become a press on an existing surface, and that needs the Explorer to be open, scrolled to the right row, and the sequence to give up quietly at each step the way doShare does."}},{id:"N57",col:"done",size:"S",tag:"content",title:"No em dashes anywhere, and a gate",note:"153 of them across 26 files, and a build step so the next one cannot land.",detail:{why:'Nam: "control the whole site to make sure we dont have em dashes thks!" A careful pass cannot hold this. The character is easy to type, easy to paste in from a document, and invisible in a diff unless you are looking for it.',done:["Em dashes are banned in string literals and allowed in comments","En dashes are kept in ranges and banned in prose, told apart by whitespace","tools/no-em-dash.mjs runs in verify beside the CSS gates"],raised:"Nam, QA 28 Aug",notes:'The interesting part was automating the replacement. A blanket comma is grammatical but leaves a splice wherever the dash was doing a colon\u2019s job, and it did that in twenty-one places. Those are colons and full stops now; the fifteen cases of ", which ..." were left alone, since a non-restrictive clause is what a comma is for.'}},{id:"N58",col:"done",size:"S",tag:"content",title:"The opening stops counting achievements out loud",note:"It hands over a different goal instead: there are bugs in here.",detail:{why:'Nam: "3. While I talk, click around if you want. Lots of bugs here ;) / 4. First, let me get my screen up." Naming a number was N30\u2019s idea and it was a good one while the achievements were the only game. They are not any more, and "all 17 achievements" is a chore handed to a stranger in the third sentence. A wink about bugs is an invitation that costs nothing to decline.',done:["Line 3 promises bugs rather than a count",'Line 4 says "First", so the share reads as the first of several things',"The test that pinned the count against the quest list is retired with the line it guarded"],raised:"Nam, script pass 28 Aug"}},{id:"N59",col:"done",size:"L",tag:"call",title:"The bug collection",note:"Twelve bugs hidden across the site, caught by repetition, pinned in a real entomology frame.",detail:{why:'Nam: "This is like the same as easter eggs, but reward a different kind of exploration: the developer\u2019s dedication ... the bugs here are different. We basically have a collection ... user needs to catch them all pokemon style." The achievements reward breadth: touch each thing once. Nothing rewarded going back to the same thing to see whether it still holds up, which is the actual habit of somebody who tests software. Repetition is the mechanic because repetition is the behaviour.',done:["A registry of twelve bugs: name, species, where it hides, the hint, and the fact","Each is caught by doing one thing three times, or by one deliberately obscure act",'Catching one raises a toast like an achievement, with the bug drawn in it, reading "New bug"',"The ended screen opens a frame: caught bugs painted, uncaught ones silhouettes","A silhouette still shows its hint. A caught bug shows the species and the facts","Every bug is an authored SVG, no bitmaps and no third-party requests","The list, the hiding places and the art are all documented in the Project spec"],raised:"Nam, script pass 28 Aug",notes:"Art was the interesting constraint. Twelve bespoke illustrations is a week of drawing, and twelve copies of one beetle is not a collection. So the drawing is parametric: eight body plans, scarab, jewel, longhorn, cicada, swallowtail, birdwing, mantis and leaf, each taking a palette and a set of proportions. A silhouette is the same geometry with one flat fill, which is why an uncaught bug has exactly the right outline and gives nothing else away."}},{id:"N60",col:"done",size:"M",tag:"content",title:"The CV section, in his own words",note:"Five lines rewritten, one split in two so the hesitation has somewhere to land.",detail:{why:'Nam went through the section line by line. The platform line was wrong in a way only he would catch: it said "Desktop, then web, then a Unity renderer embedded in a React app", and the real sequence is Desktop, Dart, Unity, React Native. The cross-team line lost its midnight-support flourish because the true list is longer and duller and includes marketing.',done:["Seven years leading front end, four players, one shared board","Desktop, then Dart, then Unity and finally Native React","Design, backend, marketing, QA",'The skills line splits, so "Claude, uh, made this whole section redundant LOL" is its own beat',"Education gains a punchline instead of trailing off"],raised:"Nam, script pass 28 Aug",notes:'The "uh" is the return of the hesitation N53 reverted, on the terms N53 set: authored, not derived. The word is in the line because Nam put it there, and the caption renderer holds on it the way it holds on a full stop. Placement is a writing decision and it is now written down.'}},{id:"N61",col:"done",size:"S",tag:"content",title:'The job requirement section ticks rather than says "check"',note:"Emoji carry the repetition, and the Oprah bit is replaced.",detail:{why:'Nam: "we can use the emoji here for check to lessen the reading load." Four spelled-out "check"s in one caption is a lot of reading for a joke about how little reading is required. And on the punchline: "here I meant to land a punchline, but I couldnt think of anything else better. Help."',done:["Lines 3 and 4 use a tick glyph instead of the word","Line 4 names the real four: front end, algorithm, architecture, QA","The Oprah line is gone, replaced with one that points at the evidence"],raised:"Nam, script pass 28 Aug",notes:'The replacement is "I ran out of requirements before I ran out of evidence." It lands because it is the only claim on this page that the page itself can settle: everything named is a thing the visitor can click.'}},{id:"N62",col:"done",size:"S",tag:"content",title:"The build section names the budget and stops selling the tests",note:'A number instead of "there is a size budget", and a line about games instead of a second test pitch.',detail:{why:'Nam: "Let\u2019s mention the actual size budget here instead of being vague about it", and on the tests line, "remove, not really relevant." He is right about the second one: the tests already have a quip, a panel and a switch that breaks them. Saying it here too is the third pitch for the same feature.',done:["The budget line says 50 kB gzipped, which is the number in build.mjs","The measurement line drops its trailing clause, the wrong measurement has its own home in the Spec panel","The tests line becomes a line about the game layer instead",'The closing line is his: "One person and an agent, one week. The most fun I have had in months"'],raised:"Nam, script pass 28 Aug"}},{id:"N63",col:"done",size:"M",tag:"call",title:"Off the clock is generous with the clips",note:"It plays every one the visitor has not found, and credits them for it.",detail:{why:'Nam: "show the achievement as the video plays. We complete these easter eggs for user. We can be generous here, now that we add in the bugs too that we will not be generous about." The two mechanics need different postures. The achievements are a guided walk of the surface and handing them over costs nothing. The bugs are the thing worth hunting, so they are never given away.',done:["It plays all the unseen clips rather than the first three","The Off the clock quest unlocks as they play",'The opening line is "And here is how I have fun after work"',"The Hollywood apology is gone"],raised:"Nam, script pass 28 Aug"}},{id:"N64",col:"done",size:"M",tag:"call",title:"The close demonstrates the three things it names",note:"Open the chat, drag the video, raise your hand: each one is performed, not described.",detail:{why:'Nam: "Each of these action, we demo it with the mouse. Might need to break it into 3 lines to trigger mouse interaction." A line that says "drag the windows" and then does nothing is the one moment in the script where the demo talks about itself instead of running.',done:["One line per action, each with its own beat","The side controls carry a data-ctl so the script can name them","A drag cue that really drags the video tile to another corner",'The plain-document line becomes "The CV is also available in home screen and after this meeting"'],raised:"Nam, script pass 28 Aug",notes:"The drag is synthetic pointer events along the hand\u2019s own path. The tile\u2019s drag handler already tolerated them, which was luck rather than design: it guards setPointerCapture in a try because a synthetic PointerEvent carries no real pointer. That guard is what makes this two lines instead of a rewrite."}},{id:"N65",col:"done",size:"M",tag:"content",title:"The personal segment, rewritten in his voice",note:"Eight answers, and two of the questions no longer have to be guessed from the answer.",detail:{why:'Nam rewrote all eight. The strongest note is on the last one: "I dont understand this question. What risk is there in hiring me LOL." He is right that it was a defensive frame borrowed from a hiring conversation he is not having. And on the collaboration answer: "This is one part where the question doesnt appear intuitively from the answer", which is a real failure, the questions are printed in the Scripts panel but they are never spoken.',done:["Why now, what he likes, strengths, weaknesses, collaboration, being wrong, the hardest thing, and why him","Two answers now restate their own question in the first clause",'"Why should we take the risk" becomes "Why me"',"The measured-things and getBoundingClientRect boasts go, the page makes that argument by existing"],raised:"Nam, script pass 28 Aug",notes:"The Google line in the second answer is the only company-specific sentence in the whole script, which is what forced N66."}},{id:"N66",col:"done",size:"S",tag:"trust",title:"Google is the default, not a code",note:"The neutral build stays reachable, it just stops being what a stranger gets.",detail:{why:'Nam: "regarding the company, I think let\u2019s all in for google first, so let\u2019s just treat the default CV (without c parameter as c = 1, so google cv is the default). Lets try our chance with google first before reusing the CV for other job ads." The multi-employer machinery was built for a reuse that has not happened yet, and it was costing the send it was actually built for: the one application in flight was the one rendering a generic heading.',done:["No code resolves to the Google pitch","?c=0 resolves to the neutral build, so the reusable version is still one parameter away","The tab title, the meeting name, the chat opener and the job-ad section all name the employer by default"],raised:"Nam, script pass 28 Aug",notes:"A default is a one-line change and an escape hatch is not. ?c=0 had to become a real code rather than an unknown one, because codeFromUrl treats an unrecognised value as absent, which now means Google."}},{id:"N67",col:"done",size:"M",tag:"call",title:"The outro counts what is left, and takes its time",note:"The tease names the real number of eggs and bugs still out there, and the silences stretch.",detail:{why:'Nam: "Lets make this dynamic. Not 2 easter eggs, but however many easter eggs left. And we add the remaining bugs too." A hardcoded two was already wrong for anyone who had found one. And on the pacing: "This is the time user is exploring the app, we want to keep the caption on for the commentary messages. Plus, the timing of the call has already finished by the goodbye, so stretching out the after goodbye doesnt cost user anything literally."',done:["Outro lines are templates, resolved against what this visitor has actually found","The line is skipped entirely when there is nothing left to tease","The silences stretch, and the two-minute cap goes up to four with them","The gaps-only-grow rule and the no-long-bubble rule still hold"],raised:"Nam, script pass 28 Aug",notes:"The cap was never about the outro being too long, it was about a visitor being trapped in something they cannot see the end of. Any input abandons it, so the cap is a promise about the worst case rather than a budget. Doubling it is safe for exactly the reason Nam gives: the interview clock stopped at the goodbye."}},{id:"T24",col:"backlog",size:"M",tag:"specs",title:"Initial payload is halfway to the ceiling",note:"24.7 kB of a 50 kB gate, up from 18.2. Still green, and the growth is real, but two deferred chunks are 17 kB and 19 kB and deserve a splitting pass before it becomes urgent."}];export{t as a,a as b,n as c,i as d,o as e,s as f,r as g};
